/bin/zsh -lc "./run_python -c 'import tempfile, pathlib, math; from app import Queue
with tempfile.TemporaryDirectory() as d:
 p=pathlib.Path(d)/\"q.db\"; a=Queue(p); b=Queue(p)
 source={\"nested\":[1,{\"ok\":True}]}; a.put(\"x\",source); source[\"nested\"][1][\"ok\"]=False
