try: a.put(\"x\",None)
except ValueError: pass
else: raise AssertionError(\"completed ID was reusable\")
a.put(\"y\",[1])
for duration in (True, False, 0, -1, float(\"inf\"), float(\"nan\")):
 try: a.claim(\"worker\",3,duration)
 except ValueError: pass
 else: raise AssertionError(f\"accepted lease {duration"'!r}")
assert a.claim("worker",3,0.25)["expires_at"]==3.25
print("contract probe passed")'"'"

